// Insert logo into nav
function insertLogos() {
	const logoContainers = document.querySelectorAll('.logo-container');
	const navLogo = document.getElementById('nav-logo');

	logoContainers.forEach((container) => {
		container.innerHTML = logoSVG;
		// Add animation to waveform bars
		animateWaveformBars(container);
	});

	if (navLogo) {
		navLogo.innerHTML = logoSVG;
		// Add animation to waveform bars
		animateWaveformBars(navLogo);
	}
}

// Animate waveform bars with seismograph drawing effect
function animateWaveformBars(container) {
	const bars = Array.from(container.querySelectorAll('.waveform-bar'));

	// Sort bars by their X position (left to right)
	const sortedBars = bars.sort((a, b) => {
		// Extract the x position from the path's d attribute or transform
		// The bars are <path> elements, so we need to get their bounding box
		const rectA = a.getBBox();
		const rectB = b.getBBox();
		return rectA.x - rectB.x; // Sort by x position, ascending
	});

	const totalBars = sortedBars.length;

	// Animation timing:
	// - Drawing phase: 2 seconds (bars appear sequentially)
	// - No repeat: animation runs once and stays visible

	const totalDuration = 2; // seconds for the entire animation
	const drawingDuration = 2; // seconds to draw all bars

	sortedBars.forEach((bar, index) => {
		// Calculate when this bar should appear
		// index 0 is leftmost, should appear first (smallest delay)
		const delayPerBar = drawingDuration / totalBars;
		const delay = (index * delayPerBar).toFixed(3);

		// Apply the animation with calculated delay
		// forwards: keeps the final state (visible) after animation completes
		bar.style.animation = `seismographDraw ${totalDuration}s linear ${delay}s forwards`;
	});
}

// ================================
// Scroll Animations with Intersection Observer
// ================================

function initScrollAnimations() {
	const observerOptions = {
		threshold: 0.1,
		rootMargin: '0px 0px -50px 0px',
	};

	const observer = new IntersectionObserver((entries) => {
		entries.forEach((entry) => {
			if (entry.isIntersecting) {
				entry.target.style.opacity = '1';
				entry.target.style.transform = 'translateY(0)';
			}
		});
	}, observerOptions);

	// Observe all elements with fade-in animations
	const animatedElements = document.querySelectorAll('.fade-in-up');
	animatedElements.forEach((el) => observer.observe(el));
}

// ================================
// Smooth Scroll for Anchor Links
// ================================

function initSmoothScroll() {
	document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
		anchor.addEventListener('click', function (e) {
			const href = this.getAttribute('href');
			if (href === '#') return;

			e.preventDefault();
			const target = document.querySelector(href);

			if (target) {
				target.scrollIntoView({
					behavior: 'smooth',
					block: 'start',
				});
			}
		});
	});
}

// ================================
// Active Navigation Link
// ================================

function setActiveNavLink() {
	const currentPage =
		window.location.pathname.split('/').pop() || 'index.html';
	const navLinks = document.querySelectorAll('.nav-link, .mobile-nav-link');

	navLinks.forEach((link) => {
		const linkPage = link.getAttribute('href');
		if (
			linkPage === currentPage ||
			(currentPage === '' && linkPage === 'index.html')
		) {
			link.classList.add('active');
		} else {
			link.classList.remove('active');
		}
	});
}

// ================================
// Parallax Effect on Scroll
// ================================

function initParallax() {
	const heroSection = document.querySelector('section.relative.min-h-screen');
	if (!heroSection) return;

	window.addEventListener('scroll', () => {
		const scrolled = window.pageYOffset;
		const parallaxElements = heroSection.querySelectorAll('.fade-in-up');

		parallaxElements.forEach((el, index) => {
			const speed = 0.5 + index * 0.1;
			const yPos = -(scrolled * speed);
			el.style.transform = `translateY(${yPos}px)`;
		});
	});
}

// ================================
// Form Validation (for contact page)
// ================================

function initFormValidation() {
	const contactForm = document.querySelector('.contact-form form');
	if (!contactForm) return;

	contactForm.addEventListener('submit', (e) => {
		e.preventDefault();

		const name = contactForm.querySelector('input[name="name"]');
		const email = contactForm.querySelector('input[name="email"]');
		const message = contactForm.querySelector('textarea[name="message"]');

		let isValid = true;

		// Basic validation
		if (!name.value.trim()) {
			showError(name, 'Name is required');
			isValid = false;
		}

		if (!email.value.trim() || !isValidEmail(email.value)) {
			showError(email, 'Valid email is required');
			isValid = false;
		}

		if (!message.value.trim()) {
			showError(message, 'Message is required');
			isValid = false;
		}

		if (isValid) {
			// In a real implementation, you'd send this to a server
			// For now, just show a success message
			showSuccessMessage();
			contactForm.reset();
		}
	});

	// Clear errors on input
	const inputs = contactForm.querySelectorAll('input, textarea');
	inputs.forEach((input) => {
		input.addEventListener('input', () => {
			clearError(input);
		});
	});
}

function isValidEmail(email) {
	return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function showError(input, message) {
	clearError(input);
	input.classList.add('border-red-500');
	const errorDiv = document.createElement('div');
	errorDiv.className = 'error-message text-red-500 text-sm mt-1';
	errorDiv.textContent = message;
	input.parentElement.appendChild(errorDiv);
}

function clearError(input) {
	input.classList.remove('border-red-500');
	const errorMessage = input.parentElement.querySelector('.error-message');
	if (errorMessage) {
		errorMessage.remove();
	}
}

function showSuccessMessage() {
	const successDiv = document.createElement('div');
	successDiv.className =
		'fixed top-24 right-4 bg-green-500 text-white px-6 py-4 rounded-lg shadow-lg z-50 animate-fadeIn';
	successDiv.innerHTML = `
        <div class="flex items-center gap-2">
            <svg class="w-6 h-6" fill="currentColor" viewBox="0 0 20 20">
                <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"/>
            </svg>
            <span>Message sent successfully!</span>
        </div>
    `;
	document.body.appendChild(successDiv);

	setTimeout(() => {
		successDiv.remove();
	}, 5000);
}

