// ================================
// Mobile Menu Toggle
// ================================

function initMobileMenu() {
	const mobileMenuButton = document.getElementById('mobile-menu-button');
	const mobileMenu = document.getElementById('mobile-menu');
	const hamburgerIcon = document.getElementById('hamburger-icon');
	const closeIcon = document.getElementById('close-icon');
	const mobileNavLinks = document.querySelectorAll('.mobile-nav-link');

	if (!mobileMenuButton || !mobileMenu || !hamburgerIcon || !closeIcon)
		return;

	function toggleMenu() {
		const menuIsOpen = !mobileMenu.classList.contains('hidden');

		if (menuIsOpen) {
			// Menu is currently open, so close it
			mobileMenu.classList.add('hidden');
			hamburgerIcon.style.setProperty('display', 'block', 'important');
			closeIcon.style.setProperty('display', 'none', 'important');
			mobileMenuButton.setAttribute('aria-expanded', 'false');
		} else {
			// Menu is currently closed, so open it
			mobileMenu.classList.remove('hidden');
			closeIcon.style.setProperty('display', 'block', 'important');
			hamburgerIcon.style.setProperty('display', 'none', 'important');
			mobileMenuButton.setAttribute('aria-expanded', 'true');
		}
	}

	// Toggle menu on button click (support both click and touch for mobile)
	function handleMenuToggle(e) {
		if (e.type === 'touchend') {
			e.preventDefault();
			e.stopPropagation();
		}
		toggleMenu();
	}

	mobileMenuButton.addEventListener('click', handleMenuToggle);
	mobileMenuButton.addEventListener('touchend', handleMenuToggle, {
		passive: false,
	});

	// Close menu when clicking a nav link
	mobileNavLinks.forEach((link) => {
		link.addEventListener('click', () => {
			toggleMenu();
			// Smooth scroll to section
			const href = link.getAttribute('href');
			if (href && href.startsWith('#')) {
				const target = document.querySelector(href);
				if (target) {
					setTimeout(() => {
						target.scrollIntoView({
							behavior: 'smooth',
							block: 'start',
						});
					}, 100);
				}
			}
		});
	});

	// Close menu when clicking outside
	document.addEventListener('click', (e) => {
		if (
			!mobileMenu.contains(e.target) &&
			!mobileMenuButton.contains(e.target) &&
			!mobileMenu.classList.contains('hidden')
		) {
			toggleMenu();
		}
	});

	// Don't close menu on scroll - allow scrolling with menu open
}

function initKeyboardNav() {
	document.addEventListener('keydown', (e) => {
		// Escape key closes mobile menu
		if (e.key === 'Escape') {
			const mobileMenu = document.getElementById('mobile-menu');
			const hamburgerIcon = document.getElementById('hamburger-icon');
			const closeIcon = document.getElementById('close-icon');
			const mobileMenuButton =
				document.getElementById('mobile-menu-button');

			if (mobileMenu && !mobileMenu.classList.contains('hidden')) {
				mobileMenu.classList.add('hidden');
				hamburgerIcon.classList.remove('hidden');
				closeIcon.classList.add('hidden');
				mobileMenuButton.setAttribute('aria-expanded', 'false');
				document.body.style.overflow = '';
			}
		}
	});
}

// ================================
// Font Loading Check
// ================================
async function checkFontLoading() {
	// Use font loading API if available
	if (document.fonts && document.fonts.load) {
		try {
			// Try to load the font explicitly
			await document.fonts.load('16px "Chinese Sthupo"');

			// Double-check with status API
			if (
				document.fonts.check &&
				document.fonts.check('16px "Chinese Sthupo"')
			) {
				document.documentElement.style.setProperty(
					'--logo-font',
					'"Chinese Sthupo", Arial, Helvetica, sans-serif',
				);
				console.log('Custom font loaded successfully');
			} else {
				useFallbackFont();
			}
		} catch (error) {
			console.log('Font loading error, using fallback:', error);
			useFallbackFont();
		}
	} else if (document.fonts && document.fonts.check) {
		// Fallback for browsers without font loading API
		const fontLoaded = document.fonts.check('16px "Chinese Sthupo"');
		if (fontLoaded) {
			document.documentElement.style.setProperty(
				'--logo-font',
				'"Chinese Sthupo", Arial, Helvetica, sans-serif',
			);
		} else {
			useFallbackFont();
		}
	}
}

function useFallbackFont() {
	console.log('Custom font not loaded, using fallback');
	document.documentElement.style.setProperty(
		'--logo-font',
		'Arial, Helvetica, sans-serif',
	);
}

function updateSVGFonts(fontFamily) {
	// Find all SVG text elements and update their font-family
	const svgTextElements = document.querySelectorAll('svg text, svg tspan');
	svgTextElements.forEach((element) => {
		element.style.fontFamily = fontFamily;
	});

	// Also check for SVG elements with font-family in style attribute
	const svgElements = document.querySelectorAll('svg');
	svgElements.forEach((svg) => {
		const style = svg.getAttribute('style') || '';
		if (style.includes('font-family')) {
			svg.setAttribute(
				'style',
				style.replace(
					/font-family:[^;]+/g,
					`font-family: ${fontFamily}`,
				),
			);
		}
	});
}

// Initialize Everything on Page Load
// ================================

document.addEventListener('DOMContentLoaded', async () => {
	await checkFontLoading();
	insertLogos();
	initScrollAnimations();
	initSmoothScroll();
	setActiveNavLink();
	initParallax();
	initFormValidation();
	initKeyboardNav();
	initMobileMenu();
	initVideoCarousel();

	// Check font loading again after a delay
	setTimeout(() => checkFontLoading(), 1000);
});

// Listen for font loading events for additional reliability
if (document.fonts && document.fonts.addEventListener) {
	document.fonts.addEventListener('loadingdone', (event) => {
		checkFontLoading();
	});
}

// ================================
// Handle page visibility for animations
// ================================

document.addEventListener('visibilitychange', () => {
	if (document.hidden) {
		// Pause animations when tab is not visible to save resources
		document.body.style.animationPlayState = 'paused';
	} else {
		document.body.style.animationPlayState = 'running';
	}
});

