let currentVideoIndex = 0;

function initVideoCarousel() {
	const carouselContainer = document.getElementById('video-carousel');
	if (!carouselContainer) return;

	// Generate carousel items
	const carouselHTML = videoData
		.map(
			(video, index) => `
        <div class="video-carousel-item ${
			index === 0 ? 'active' : ''
		}" data-index="${index}" data-video-id="${
				video.id
			}" role="button" tabindex="0" aria-label="Watch ${
				video.title
			}" onkeypress="handleVideoKeyPress(event, ${index})">
          <div class="relative">
            <img 
              src="https://img.youtube.com/vi/${video.id}/mqdefault.jpg" 
              alt="${video.title}"
              loading="lazy"
              class="w-full aspect-video object-cover"
            />
            <div class="video-carousel-overlay">
              <div class="video-play-icon">
                <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                  <path d="M8 5v14l11-7z"/>
                </svg>
              </div>
            </div>
          </div>
          <div class="video-carousel-title">${video.title}</div>
        </div>
      `,
		)
		.join('');

	carouselContainer.innerHTML = carouselHTML;

	// Add click handlers to carousel items
	const carouselItems = carouselContainer.querySelectorAll(
		'.video-carousel-item',
	);
	carouselItems.forEach((item) => {
		item.addEventListener('click', handleVideoClick);
	});
}

function handleVideoClick(event) {
	const clickedItem = event.currentTarget;
	const index = parseInt(clickedItem.getAttribute('data-index'));
	changeVideo(index);
}

function handleVideoKeyPress(event, index) {
	if (event.key === 'Enter' || event.key === ' ') {
		event.preventDefault();
		changeVideo(index);
	}
}

function changeVideo(index) {
	if (index === currentVideoIndex) return;

	currentVideoIndex = index;
	const video = videoData[index];

	// Update main video container
	const mainVideoContainer = document.getElementById('main-video-container');
	if (mainVideoContainer) {
		// Check video source type
		if (video.source === 'googledrive' && video.driveId) {
			// Show Google Drive embed directly
			mainVideoContainer.innerHTML = `
				<iframe id="main-video" width="1224" height="689"
					src="https://drive.google.com/file/d/${video.driveId}/preview" 
					title="${video.title}"
					frameborder="0"
					allow="autoplay"
					allowfullscreen
					class="w-full h-full"></iframe>
			`;
		} else if (video.embeddable === false) {
			// Show thumbnail link for non-embeddable YouTube videos
			mainVideoContainer.innerHTML = `
				<a href="https://youtu.be/${video.id}" target="_blank" 
					class="relative w-full h-full block group/thumb">
					<img 
						src="https://img.youtube.com/vi/${video.id}/maxresdefault.jpg" 
						alt="${video.title}"
						class="w-full h-full object-cover rounded-lg"
						onerror="this.src='https://img.youtube.com/vi/${video.id}/hqdefault.jpg'"
					/>
					<div class="absolute inset-0 bg-black/30 group-hover/thumb:bg-black/20 transition-colors rounded-lg flex items-center justify-center">
						<div class="w-20 h-20 bg-brand-orange/90 group-hover/thumb:bg-brand-orange rounded-full flex items-center justify-center transition-all group-hover/thumb:scale-110">
							<svg class="w-10 h-10 text-white ml-1" fill="currentColor" viewBox="0 0 24 24">
								<path d="M8 5v14l11-7z"/>
							</svg>
						</div>
					</div>
				</a>
			`;
		} else {
			// Show YouTube iframe for embeddable videos
			mainVideoContainer.innerHTML = `
				<iframe id="main-video" width="1224" height="689"
					src="https://www.youtube.com/embed/${video.id}?autoplay=1" 
					title="${video.title}"
					frameborder="0"
					allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
					referrerpolicy="strict-origin-when-cross-origin" 
					allowfullscreen
					class="w-full h-full"></iframe>
			`;
		}
	}

	// Update title and description
	const videoTitle = document.getElementById('video-title');
	const videoDescription = document.getElementById('video-description');
	if (videoTitle) videoTitle.textContent = video.title;
	if (videoDescription) videoDescription.textContent = video.description;

	// Update carousel active state
	const carouselItems = document.querySelectorAll('.video-carousel-item');
	carouselItems.forEach((item, i) => {
		if (i === index) {
			item.classList.add('active');
			// Scroll carousel item into view
			item.scrollIntoView({
				behavior: 'smooth',
				block: 'nearest',
				inline: 'start',
			});
		} else {
			item.classList.remove('active');
		}
	});
}

// Scroll Effects - Fade in/out all sections with smooth transitions and active nav
document.addEventListener('DOMContentLoaded', () => {
	// Get all sections
	const allSections = document.querySelectorAll('section');
	const navLinks = document.querySelectorAll('.nav-link');
	const nav = document.querySelector('nav');

	function handleScroll() {
		const windowHeight = window.innerHeight;
		const scrollY = window.scrollY;

		// Add scrolled class to nav when past hero section
		if (scrollY > windowHeight * 0.5) {
			nav.classList.add('scrolled');
		} else {
			nav.classList.remove('scrolled');
		}

		// Update active nav link based on scroll position
		let currentSection = '';
		let closestSection = '';
		let closestDistance = Infinity;

		allSections.forEach((section) => {
			const rect = section.getBoundingClientRect();
			const sectionTop = rect.top;
			const sectionHeight = rect.height;
			const sectionCenter = sectionTop + sectionHeight / 2;

			// Calculate distance from viewport center
			const viewportCenter = windowHeight / 2;
			const distanceFromCenter = Math.abs(sectionCenter - viewportCenter);

			// Track the closest section to viewport center
			if (distanceFromCenter < closestDistance) {
				closestDistance = distanceFromCenter;
				closestSection = section.id;
			}

			// Also check if section is significantly in viewport (more lenient)
			if (
				sectionTop <= windowHeight * 0.4 &&
				sectionTop + sectionHeight > windowHeight * 0.1
			) {
				currentSection = section.id;
			}
		});

		// Use the closest section if no section meets the viewport criteria
		if (!currentSection && closestSection) {
			currentSection = closestSection;
		}

		// Update nav link active states
		navLinks.forEach((link) => {
			const href = link.getAttribute('href');
			if (href === `#${currentSection}`) {
				link.classList.add('active');
			} else {
				link.classList.remove('active');
			}
		});

		// Apply fade effects to all sections
		allSections.forEach((section) => {
			const rect = section.getBoundingClientRect();
			const sectionTop = rect.top;
			const sectionHeight = rect.height;
			const sectionBottom = rect.bottom;

			// Calculate opacity and transform based on section position
			let opacity = 1;
			let translateY = 0;

			// Determine section state relative to viewport
			if (sectionTop > windowHeight) {
				// Section is below viewport - fade out as it scrolls up
				const fadeStart = windowHeight * 0.2;
				const fadeDistance = windowHeight * 0.8; // Increased fade distance
				const fadeProgress = Math.max(
					0,
					Math.min(1, (sectionTop - fadeStart) / fadeDistance),
				);
				opacity = Math.max(0, 1 - fadeProgress); // Ensure opacity goes to 0
				translateY = fadeProgress * 120; // Increased movement
			} else if (sectionBottom < 0) {
				// Section is above viewport - fade out as it scrolls up
				const fadeDistance = windowHeight * 0.8; // Increased fade distance
				const fadeProgress = Math.max(
					0,
					Math.min(1, -sectionBottom / fadeDistance),
				);
				opacity = Math.max(0, 1 - fadeProgress); // Ensure opacity goes to 0
				translateY = -fadeProgress * 120; // Increased movement
			} else {
				// Section is in viewport - fade in as it comes into view
				// Use section height (capped at viewport) so short sections can reach full opacity
				const fadeDistance = Math.min(sectionHeight, windowHeight);

				// Calculate fade progress based on how much of section is visible
				const visibleHeight =
					Math.min(sectionBottom, windowHeight) -
					Math.max(sectionTop, 0);
				const fadeProgress = Math.max(
					0,
					Math.min(1, visibleHeight / fadeDistance),
				);
				opacity = Math.max(0.2, fadeProgress); // Minimum opacity for visibility
				translateY = (1 - fadeProgress) * 100; // Increased movement
			}

			// Apply effects to section
			section.style.opacity = opacity;
			section.style.transform = `translateY(${translateY}px)`;
		});
	}

	// Throttle scroll events for better performance
	let ticking = false;
	window.addEventListener('scroll', () => {
		if (!ticking) {
			requestAnimationFrame(() => {
				handleScroll();
				ticking = false;
			});
			ticking = true;
		}
	});
});
